css:
.ej2474-container {
  font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1c2b30;
  background-color: #f6f5f2;
  padding: 18px;
  border-radius: 10px;
  max-width: 1180px;
  margin: 0 auto;
  box-sizing: border-box;
}
.ej2474-container *, .ej2474-container *::before, .ej2474-container *::after { box-sizing: border-box; }
.ej2474-header { border-bottom: 3px solid #1d5c63; padding-bottom: 12px; margin-bottom: 14px; }
.ej2474-header h1 { font-size: 1.6rem; margin: 0 0 4px 0; color: #123c42; }
.ej2474-subtitle { font-size: 1rem; margin: 0 0 10px 0; color: #3c5058; }
.ej2474-voice { font-size: 0.94rem; line-height: 1.55; margin: 0; color: #2a3d44; }
.ej2474-badge {
  display: inline-block;
  background-color: #1d5c63;
  color: #ffffff;
  border-radius: 4px;
  padding: 2px 8px;
  margin-right: 6px;
  font-weight: 600;
}
.ej2474-how {
  background-color: #ffffff;
  color: #1c2b30;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 14px;
}
.ej2474-how summary { font-weight: 700; color: #123c42; cursor: pointer; }
.ej2474-how-steps { margin: 8px 0; padding-left: 22px; font-size: 0.92rem; line-height: 1.5; color: #26383f; }
.ej2474-how-score { font-size: 0.88rem; line-height: 1.5; color: #26383f; margin: 6px 0 0 0; }
.ej2474-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 10px;
  margin-bottom: 18px;
}
.ej2474-card {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-left: 4px solid #1d5c63;
  border-radius: 8px;
  padding: 10px 12px;
}
.ej2474-card-label { font-size: 0.82rem; color: #47585f; margin-bottom: 3px; }
.ej2474-card-value { font-size: 1.22rem; font-weight: 700; color: #123c42; }
.ej2474-card-sub { font-size: 0.8rem; color: #55666d; margin-top: 2px; }
.ej2474-score { color: #1f4e79; }
.ej2474-round {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
}
.ej2474-round-title { font-size: 1.16rem; margin: 0 0 8px 0; color: #123c42; }
.ej2474-h3 { font-size: 1rem; margin: 16px 0 8px 0; color: #123c42; }
.ej2474-brief {
  font-size: 0.95rem;
  line-height: 1.55;
  color: #26383f;
  background-color: #e9f3ef;
  border-left: 3px solid #1d5c63;
  padding: 10px 12px;
  border-radius: 0 6px 6px 0;
  margin: 0 0 14px 0;
}
.ej2474-reveal {
  font-size: 0.95rem;
  line-height: 1.55;
  color: #2e2a22;
  background-color: #fbf6ea;
  border: 1px solid #d9c9a3;
  border-left: 4px solid #8a5a12;
  padding: 10px 12px;
  border-radius: 6px;
  margin: 0 0 12px 0;
}
.ej2474-ka {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 10px;
  margin: 0 0 6px 0;
}
.ej2474-ka-col { border-radius: 6px; padding: 8px 12px; font-size: 0.9rem; line-height: 1.5; }
.ej2474-ka-col h3 { font-size: 0.92rem; margin: 0 0 4px 0; }
.ej2474-ka-col ul { margin: 0; padding-left: 18px; }
.ej2474-ka-known { background-color: #eef5f1; color: #1f3a30; border-left: 4px solid #2f6b4f; }
.ej2474-ka-known h3 { color: #1f4d38; }
.ej2474-ka-assumed { background-color: #fdf3ea; color: #3e2a17; border-left: 4px solid #9a5418; }
.ej2474-ka-assumed h3 { color: #6e3a0c; }
.ej2474-debate {
  background-color: #eef1f8;
  color: #1f2a44;
  border-left: 4px solid #33467a;
  border-radius: 6px;
  padding: 8px 12px;
  margin: 14px 0;
  font-size: 0.92rem;
  line-height: 1.5;
}
.ej2474-debate h3 { font-size: 0.92rem; margin: 0 0 4px 0; color: #24335c; }
.ej2474-debate p { margin: 0; }
.ej2474-two {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 14px;
  align-items: start;
}
.ej2474-small { font-size: 0.86rem; line-height: 1.5; color: #3d4f56; margin: 4px 0 8px 0; }
.ej2474-caveat { color: #6e3a0c; }
.ej2474-quotes { margin: 0 0 6px 0; padding-left: 18px; font-size: 0.88rem; line-height: 1.5; color: #26383f; }
.ej2474-tablewrap { width: 100%; overflow-x: auto; margin: 0 0 8px 0; }
.ej2474-info, .ej2474-data {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  color: #1c2b30;
  background-color: #ffffff;
}
.ej2474-info th, .ej2474-info td, .ej2474-data th, .ej2474-data td {
  border: 1px solid #e0d9d2;
  padding: 6px 8px;
  text-align: left;
  vertical-align: top;
  line-height: 1.4;
}
.ej2474-info thead th, .ej2474-data thead th { background-color: #e9f3ef; color: #123c42; }
.ej2474-info tbody th, .ej2474-data tbody th { background-color: #f8f6f3; color: #1c2b30; font-weight: 600; }
.ej2474-data td { white-space: nowrap; }
.ej2474-data caption { caption-side: top; text-align: left; font-weight: 700; color: #123c42; padding: 4px 0; }
.ej2474-na { color: #7a4a14; font-style: italic; }
.ej2474-see {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 12px;
}
.ej2474-see-card {
  background-color: #f9fafb;
  color: #1c2b30;
  border: 1px dashed #7d949c;
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 0.88rem;
}
.ej2474-see-q { font-weight: 600; margin: 0 0 8px 0; color: #123c42; }
.ej2474-see-opts { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 6px; }
.ej2474-see-opt {
  background-color: #ffffff;
  color: #1c2b30;
  border: 1px solid #b9c6cb;
  border-radius: 6px;
  padding: 6px 8px;
  line-height: 1.35;
}
.ej2474-see-none { background-color: #f1efeb; color: #3d4f56; }
.ej2474-see-dual { margin: 8px 0 0 0; color: #3d4f56; font-style: italic; }
.ej2474-see-line { margin: 0 0 6px 0; }
.ej2474-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 12px;
  margin-top: 12px;
}
.ej2474-simgrid { grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); margin-bottom: 10px; }
.ej2474-field { display: flex; flex-direction: column; }
.ej2474-field label { font-size: 0.87rem; font-weight: 600; color: #2a3d44; margin-bottom: 4px; }
.ej2474-container select {
  background-color: #ffffff;
  color: #1c2b30;
  border: 1px solid #7d949c;
  border-radius: 5px;
  padding: 7px 8px;
  font-size: 0.94rem;
  width: 100%;
}
.ej2474-container select:disabled { background-color: #eceae6; color: #4d5f66; }
.ej2474-container option { background-color: #ffffff; color: #1c2b30; }
.ej2474-live {
  font-size: 0.9rem;
  line-height: 1.5;
  color: #1f2a44;
  background-color: #eef1f8;
  border-radius: 6px;
  padding: 8px 12px;
  margin: 12px 0 0 0;
}
.ej2474-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.ej2474-btn-primary {
  background-color: #1d5c63;
  color: #ffffff;
  border: 1px solid #1d5c63;
  border-radius: 6px;
  padding: 10px 20px;
  font-size: 0.97rem;
  font-weight: 600;
  cursor: pointer;
}
.ej2474-btn-primary:hover { background-color: #123c42; }
.ej2474-container button:disabled { opacity: 0.55; cursor: not-allowed; }
.ej2474-container :focus-visible { outline: 3px solid #1f4e79; outline-offset: 2px; }
.ej2474-lab {
  background-color: #ffffff;
  color: #1c2b30;
  border: 2px solid #8a5a12;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 18px;
}
.ej2474-lab-title { font-size: 1.16rem; margin: 0 0 6px 0; color: #5a3a08; }
.ej2474-lab-head { font-size: 0.9rem; color: #2e2a22; margin: 0 0 8px 0; }
.ej2474-caveats { margin: 4px 0 8px 0; padding-left: 18px; font-size: 0.86rem; line-height: 1.5; color: #4a3720; }
.ej2474-sim { margin-bottom: 10px; }
.ej2474-history {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 12px;
  overflow-x: auto;
}
.ej2474-history table { width: 100%; border-collapse: collapse; font-size: 0.88rem; color: #1c2b30; }
.ej2474-history th {
  text-align: left;
  background-color: #e9f3ef;
  color: #1c2b30;
  border-bottom: 2px solid #d6cfc8;
  padding: 6px 8px;
}
.ej2474-history td { border-bottom: 1px solid #e6e0da; padding: 6px 8px; }
.ej2474-charts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}
.ej2474-chart {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 12px;
}
.ej2474-cm { font-size: 0.95rem; color: #1c2b30; }
.ej2474-cm-score { font-size: 2.3rem; font-weight: 800; color: #123c42; }
.ej2474-cm-max { font-size: 1.05rem; font-weight: 600; color: #55666d; }
.ej2474-cm-verdict { font-size: 1.1rem; font-weight: 700; color: #1f4e79; margin-bottom: 10px; }
.ej2474-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
.ej2474-cm-kpi {
  background-color: #e9f3ef;
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 0.88rem;
  color: #26383f;
}
.ej2474-cm-bot { margin: 6px 0; padding: 8px 10px; background-color: #eef3f6; color: #1c2b30; border-left: 4px solid #23495e; border-radius: 4px; }
.ej2474-cm-equiv { font-size: 0.88rem; color: #3d4f56; font-style: italic; }
.ej2474-cm-h { font-size: 1rem; margin: 14px 0 4px 0; color: #123c42; }
.ej2474-cm-insights, .ej2474-cm-questions { margin: 0; padding-left: 20px; line-height: 1.55; }
@media (max-width: 600px) {
  .ej2474-container { padding: 12px; }
  .ej2474-header h1 { font-size: 1.3rem; }
  .ej2474-data td { white-space: normal; }
}
@media (prefers-reduced-motion: reduce) {
  .ej2474-container * { transition: none !important; animation: none !important; }
}

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "2474";
    var MODE = "";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        // 1.3: only the texts decide. Numeric values alone (0, 1, 2) no longer keep a decision in order: many
        // decisions with named options use them, and a fixed order there let the first or last option win.
        var nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    /* 8. Text follows the language. The tables are the sim's own (vcI18n on the platform, .trans in the
       Open player). A string is replaced only when it is another language's value for a key the current
       language also has, and never when it is also a value of the current language itself. */
    var trCache = { lang: null, maps: null };
    function rawLang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        return String(l).toLowerCase().slice(0, 2);
    }
    function tables() {
        try { if (window.vcI18n && window.vcI18n._translations && typeof window.vcI18n._translations === "object") { var t = window.vcI18n._translations; for (var k in t) { if (t[k] && typeof t[k] === "object") { return t; } } } } catch (e) {}
        try { var f = sim(); if (f && f.trans && typeof f.trans === "object") { return f.trans; } } catch (e) {}
        return null;
    }
    function flat(o, pre, out, d) {
        if (!o || typeof o !== "object" || d > 4) { return out; }
        for (var k in o) {
            if (!Object.prototype.hasOwnProperty.call(o, k)) { continue; }
            var v = o[k];
            if (typeof v === "string") { out[pre + k] = v; }
            else if (v && typeof v === "object" && !Array.isArray(v)) { flat(v, pre + k + ".", out, d + 1); }
        }
        return out;
    }
    function squash(s) { return String(s).replace(/\s+/g, " ").replace(/^ | $/g, ""); }
    var decoder = null;
    function decode(s) {
        if (s.indexOf("&") < 0) { return s; }
        try { decoder = decoder || document.createElement("textarea"); decoder.innerHTML = s; return decoder.value; } catch (e) { return s; }
    }
    // a value with inline markup is several text nodes on the page: one piece per stretch between tags
    function pieces(v) {
        var p = String(v).split(/<[^>]*>/);
        for (var i = 0; i < p.length; i++) { p[i] = decode(p[i]); }
        return p;
    }
    var LETTER = /[A-Za-zÀ-ɏ]/;
    function quote(s) { return s.replace(/[.*+?^$()|[\]\\]/g, "\\$&"); }
    function template(a, b) {
        var parts = a.split(/\{(\w+)\}/), names = [], rx = "", lit = 0;
        for (var i = 0; i < parts.length; i++) {
            if (i % 2) { names.push(parts[i]); rx += (i === parts.length - 2 && parts[i + 1] === "") ? "([^\\s.,;:!?)]+)" : "(.+?)"; }
            else { rx += quote(parts[i]); lit += parts[i].replace(/\s/g, "").length; }
