            var d = st.decisions || {};
            var rec = {};
            var self = this;
            (this.CONTROLS[period] || []).forEach(function(key) {
                rec[key] = self._str(key, self.DEFAULTS[key]);
            });
            d['round' + period] = rec;
            var p;
            for (p = period + 1; p <= this.ROUNDS.length; p++) { delete d['round' + p]; }
            st.decisions = d;
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period, overallScore: r.overallScore, score: r.overallScore, roundScore: r.roundScore,
                profit: r.profit, share: r.share, err: r.err, spend: r.spend, units: r.units
            };
        }

        _computeRound(state) {
            var ds = state.domainState;
            var period = state.currentPeriod;
            var keys = ['profitHistory', 'shareHistory', 'errHistory', 'spendHistory', 'unitsHistory', 'scoreHistory', 'roundScores'];
            keys.forEach(function(k) { ds[k] = []; });
            var rs = null;
            var i;
            for (i = 1; i <= period; i++) {
                var r = this._roundScore(state, i);
                var m = r.m;
                ds.profitHistory[i - 1] = Math.round(m.profit);
                ds.shareHistory[i - 1] = Math.round(m.share * 1000) / 10;
                ds.errHistory[i - 1] = Math.round(m.err * 1000) / 10;
                ds.spendHistory[i - 1] = Math.round(m.spend);
                ds.unitsHistory[i - 1] = Math.round(m.units);
                ds.scoreHistory[i - 1] = r.score;
                ds.roundScores[i - 1] = r.score;
                if (i === period) { rs = r; }
            }
            ds.finished = (period >= state.maxPeriods);
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            ds.last = {
                roundScore: rs.score, profit: ds.profitHistory[period - 1], share: ds.shareHistory[period - 1],
                err: ds.errHistory[period - 1], spend: ds.spendHistory[period - 1], units: ds.unitsHistory[period - 1]
            };
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return {
                period: period, overallScore: score, roundScore: rs.score, profit: ds.last.profit, share: ds.last.share,
                err: ds.last.err, spend: ds.last.spend, units: ds.last.units
            };
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                num += w[p - 1] * this._roundScore(state, p).score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

