        _clone(o) {
            return JSON.parse(JSON.stringify(o));
        }

        _net(price) {
            return price / this.C.VAT * (1.0 - this.C.DEALER);
        }

        _design(rk, mk, bk) {
            var r = this.RANGE_IDX[rk];
            if (r === undefined) { r = 1; }
            var m = (mk === 'central') ? 1 : 0;
            var rem = (bk === 'extraible') ? 1 : 0;
            return {
                r: r, m: m, rem: rem, war: 0, gps: 0,
                kg: this.RANGE_KG[r] + m * this.MOTOR_KG + rem * this.REM_KG,
                uc: this.RANGE_UC[r] + m * this.MOTOR_UC + rem * this.REM_UC
            };
        }

        _util(par, q, isRival) {
            var c = this.C;
            var rng = par.rng[Math.max(0, Math.min(3, q.r))];
            var v = par.asc + rng + par.mot * q.m + par.kg * (c.KG_REF - q.kg) + par.rem * q.rem
                + par.war * q.war + par.gps * q.gps + par.pr * q.p / 100.0;
            if (isRival) { v += par.brand; }
            return v;
        }

        _segChoice(par, prods, rival, lam) {
            var L = (lam && lam > 0) ? lam : 1.0;
            var ek = [];
            var sumk = 0.0;
            var i;
            for (i = 0; i < prods.length; i++) {
                var e = Math.exp(this._util(par, prods[i], false) / L);
                ek.push(e);
                sumk += e;
            }
            var iv = (sumk > 0) ? Math.exp(L * Math.log(sumk)) : 0.0;
            var er = Math.exp(this._util(par, rival, true));
            var den = 1.0 + er + iv;
            var pn = iv / den;
            var out = { prods: ek.map(function(v) { return (sumk > 0) ? pn * v / sumk : 0.0; }), rival: er / den, none: 1.0 / den };
            out.rivalAlone = er / (1.0 + er);
            return out;
        }

        _demand(model, prods, rival, w, reach) {
            var c = this.C;
            var pm = c.M_YEAR / 12.0 * w;
            var lam = model.lam;
            if (model.lamMin && prods.length === 2) {
                var a0 = prods[0], a1 = prods[1];
                var dist = Math.abs(a0.r - a1.r) + Math.abs(a0.m - a1.m) + Math.abs(a0.rem - a1.rem) + Math.abs(a0.p - a1.p) / 400.0;
                lam = Math.min(model.lam, model.lamMin + 0.15 * Math.min(3.0, dist));
            }
            var su = this._segChoice(model.U, prods, rival, lam);
            var se = this._segChoice(model.E, prods, rival, lam);
            var units = [];
            var i;
            for (i = 0; i < prods.length; i++) {
                units.push(pm * reach * (c.MIX_U * su.prods[i] + (1.0 - c.MIX_U) * se.prods[i]));
            }
            var rv = pm * (c.MIX_U * (reach * su.rival + (1.0 - reach) * su.rivalAlone)
                + (1.0 - c.MIX_U) * (reach * se.rival + (1.0 - reach) * se.rivalAlone));
            var tot = 0.0;
            for (i = 0; i < units.length; i++) { tot += units[i]; }
            return { units: units, total: tot, rival: rv, U: su, E: se };
        }

        _baseLevels(par) {
            return { rng: par.rng[2], mot: par.mot, kg: par.kg * 5.0, rem: par.rem, war: par.war, gps: par.gps };
        }

        _study(e, at, s) {
            var c = this.C;
            var self = this;
            var res = { method: e, attrs: at, sample: s, measured: {}, se: { U: {}, E: {} }, none: (e === 'ninguno') };
            res.cost = this.STUDY[e] + ((e === 'ninguno') ? 0.0 : (this.ATTR_EXTRA[at] + this.SAMPLE_COST[s]));
            res.weeks = this.WEEKS[e] + ((e !== 'ninguno' && at === 'voz') ? 3 : 0);
            if (e === 'ninguno') {
                res.model = { lam: 1.0, U: this._clone(this.ENG), E: this._clone(this.ENG) };
                ['rng', 'mot', 'kg'].forEach(function(k) { res.measured[k] = false; });
                res.mixU = c.MIX_U;
                return res;
            }
            var list = this.ATTRS[at];
            ['rng', 'mot', 'kg', 'rem', 'war', 'gps'].forEach(function(k) { res.measured[k] = list.indexOf(k) >= 0; });
            var mf = (e === 'autoexplicado') ? 0.8 : 1.0;
            var af = (at === 'todo' && e !== 'autoexplicado') ? 1.5 : 1.0;
            var n = this.SAMPLE_N[s];
            var mix = this.SAMPLE_MIX[s];
            var nSeg = { U: n * mix, E: n * (1.0 - mix) };
            res.n = n; res.nU = Math.round(nSeg.U); res.nE = Math.round(nSeg.E); res.mixU = mix;
            var model = { lam: 1.0 };
            ['U', 'E'].forEach(function(g) {
                var t = self._clone(self.TRUTH[g]);
                if (s === 'clientes') {
                    t.asc += 0.2;
                    if (g === 'U') { t.pr *= 0.85; t.rem *= 0.6; }
                }
                if (s === 'redes') { t.brand -= 0.40; t.asc += 0.15; }
                if (e === 'autoexplicado') {
                    t.pr *= 0.65;
                    t.asc += 0.7;
                    var b = self._baseLevels(t);
                    var sum = 0.0, cnt = 0;
                    list.forEach(function(k) { sum += b[k]; cnt += 1; });
                    var avg = cnt ? sum / cnt : 0.0;
                    list.forEach(function(k) {
                        var nb = 0.7 * b[k] + 0.3 * avg;
                        var f = (b[k] !== 0) ? nb / b[k] : 1.0;
                        if (k === 'rng') { t.rng = [0.0, t.rng[1] * f, t.rng[2] * f, t.rng[3] * f]; }
                        else { t[k] = t[k] * f; }
                    });
                } else if (e === 'cbc_hipotetico') {
                    t.pr *= 0.75;
                    t.asc += 0.45;
                }
                var z = self.Z[s][g];
                var sq = Math.sqrt(nSeg[g]);
                var se = {};
                Object.keys(self.SE_K).forEach(function(k) { se[k] = self.SE_K[k] / sq * mf * af; });
                t.asc += z.asc * se.asc;
                t.pr += z.pr * se.pr;
                t.brand += z.brand * se.brand;
                if (res.measured.rng) {
                    var r2 = t.rng[2] + z.rng * se.rng;
                    var r1 = t.rng[1] + z.rng * se.rng * 0.7;
                    t.rng = [0.0, r1, r2, r2 + (r2 - r1)];
                } else {
                    t.rng = [0.0, 0.0, 0.0, 0.0];
                }
                ['mot', 'kg', 'rem', 'war', 'gps'].forEach(function(k) {
                    if (res.measured[k]) { t[k] += z[k] * se[k]; } else { t[k] = 0.0; }
                });
                se.rng1 = se.rng * 0.7;
                res.se[g] = se;
                model[g] = t;
            });
            res.model = model;
            return res;
        }

        _withAssume(study, assumeEur) {
            if (!assumeEur) { return study.model; }
            var m = this._clone(study.model);
            ['U', 'E'].forEach(function(g) {
                var par = m[g];
                var u = assumeEur / 100.0 * (-par.pr);
                ['mot', 'rem', 'war', 'gps'].forEach(function(k) {
                    if (!study.measured[k]) { par[k] = u; }
                });
            });
            return m;
        }

        _launchForecast(study, prod, price) {
            if (study.none) { return this.C.SALES_FORECAST * this.C.W_LAUNCH / 12.0; }
            var q = this._clone(prod); q.p = price;
            return this._demand(study.model, [q], this.RIVAL0, this.C.W_LAUNCH, 1.0).total;
        }

        _agencyPick(study) {
            if (study.none) { return ['r120', 'central', 'integrada', 'p2890']; }
            var best = null;
            var self = this;
            this.RANGE_KEYS.forEach(function(rk) {
                ['buje', 'central'].forEach(function(mk) {
                    ['integrada', 'extraible'].forEach(function(bk) {
                        var d = self._design(rk, mk, bk);
                        self.PRICES.forEach(function(pk) {
                            var p = self.PRICE[pk];
                            var val = self._launchForecast(study, d, p) * (self._net(p) - d.uc);
                            if (best === null || val > best[0] + 1e-9) { best = [val, rk, mk, bk, pk]; }
                        });
                    });
                });
            });
            return [best[1], best[2], best[3], best[4]];
        }

        _active(dec, period) {
            var a = {};
            var i;
            for (i = 0; i < this.KEYS.length; i++) {
                var g = this.KEYS[i];
                if (this.ROUND_OF[g] <= period) {
                    var v = dec[g];
                    a[g] = (v === undefined || v === null || v === '') ? this.DEFAULTS[g] : v;
                } else {
                    a[g] = this.REF[g];
                }
            }
            if (a.autonomia2 === null) {
                var pick = this._agencyPick(this._study(a.metodo1, a.atributos1, a.muestra1));
                a.autonomia2 = pick[0]; a.motor2 = pick[1]; a.bateria2 = pick[2]; a.precio2 = pick[3];
            }
            return a;
        }

        _prods29(a, base, war) {
            var c = this.C;
            var main = this._clone(base);
            main.war = war ? 1 : 0;
            var up = a.mejora4;
            if (up === 'autonomia') { main.r = Math.min(3, main.r + 1); main.kg += c.UPG_RANGE_KG; main.uc += c.UPG_RANGE_UC; }
            else if (up === 'peso') { main.kg -= c.UPG_KG; main.uc += c.UPG_KG_UC; }
            else if (up === 'gps') { main.gps = 1; main.uc += c.UPG_GPS_UC; }
            else if (up === 'rebaja') { main.p -= c.UPG_CUT; }
            var list = [main];
            var fix = 0.0;
            var ex = this.EXT[a.gama3];
            if (ex) {
                list.push({ r: ex.r, m: ex.m, kg: ex.kg, rem: ex.rem, war: war ? 1 : 0, gps: 0, p: ex.p, uc: ex.uc });
                fix = ex.fix;
            }
            var wc = war ? c.WAR_COST : 0.0;
            list.forEach(function(q) { q.ucAll = q.uc + wc; });
            return { list: list, fix: fix };
        }

        _run(dec, period) {
            var c = this.C;
            var T = this.TRUTH;
            var a = this._active(dec, period);
            var st = this._study(a.metodo1, a.atributos1, a.muestra1);
            var d = this._design(a.autonomia2, a.motor2, a.bateria2);
            var price = this.PRICE[a.precio2];
            var prod = this._clone(d); prod.p = price;
            var fraw = this._launchForecast(st, d, price);
            var q1 = Math.min(c.CAP_RUN, this.SERIE[a.serie2] * fraw);
            var dm1 = this._demand(T, [prod], this.RIVAL0, c.W_LAUNCH, c.REACH28);
            var d1 = dm1.total;
            var sold1 = Math.min(q1, d1);
            var left1 = Math.max(0.0, q1 - d1);
            var lost1 = d1 - sold1;
            var resp = a.respuesta3;
            var war = (resp === 'garantia');
            var adv = (resp === 'publicidad');
            var p2 = (resp === 'igualar') ? price - c.MATCH_CUT : price;
            var reach2 = c.REACH28 + (adv ? c.ADV_REACH28 : 0.0);
            var prod2 = this._clone(prod); prod2.p = p2; prod2.war = war ? 1 : 0;
            var dm2 = this._demand(T, [prod2], this.RIVAL_CUT, c.W_AUTUMN, reach2);
            var d2 = dm2.total;
            var f2est = this._demand(st.model, [prod2], this.RIVAL_CUT, c.W_AUTUMN, 1.0).total;
            var fromStock = Math.min(left1, d2);
            var writtenOff = left1 - fromStock;
            var wc = war ? c.WAR_COST : 0.0;
            var rev28 = sold1 * this._net(price) + fromStock * this._net(p2 - c.MARKDOWN) + (d2 - fromStock) * this._net(p2)
                + writtenOff * (d.uc - c.WRITE_OFF);
            var cost28 = q1 * d.uc + (d2 - fromStock) * d.uc + d2 * wc;
            var fixed28 = c.LAUNCH_FIX + c.MKT_YEAR * 0.75 + c.TEAM_YEAR + (adv ? c.ADV_28 : 0.0);
            var profit28 = rev28 - cost28 - fixed28 - st.cost;
            var u28 = sold1 + d2;
            var t28 = dm1.rival + dm2.rival + c.LOST_TO_RIVAL * lost1;
            var share28 = u28 / (u28 + t28);
            var reach29 = this._clamp(c.REACH29 + (adv ? c.ADV_REACH29 : 0.0) + c.SHELF * (share28 - c.SHELF_REF), c.REACH_MIN, c.REACH_MAX);
            var base29 = this._clone(prod2);
            base29.war = 0;
            var pr29 = this._prods29(a, base29, war);
            var dm29 = this._demand(T, pr29.list, this.RIVAL29, c.W_YEAR, reach29);
            var d29 = dm29.total;
            var f29est = this._demand(st.model, pr29.list, this.RIVAL29, c.W_YEAR, 1.0).total;
            var ratio2 = (f2est > 0) ? d2 / f2est : 1.0;
            var calib = f29est * ratio2 * (reach29 / reach2);
            var pv = a.prevision4;
            var recal = 0.0, q29;
            if (pv === 'calibrar') { q29 = calib; recal = c.RECAL_COST; }
            else if (pv === 'colchon') { q29 = calib * c.BUFFER; recal = c.RECAL_COST; }
            else if (pv === 'pedidos') { q29 = d29 * c.ORDERS; }
            else { q29 = sold1 / c.LAUNCH_MONTHS * 12.0; }
            var fill = Math.min(1.0, q29 / d29);
            var sold29 = d29 * fill;
            var left29 = Math.max(0.0, q29 - d29);
            var contrib29 = 0.0;
            var units29 = [];
            var i;
            for (i = 0; i < pr29.list.length; i++) {
                var qq = pr29.list[i];
                var su = dm29.units[i] * fill;
                units29.push(su);
                contrib29 += su * (this._net(qq.p) - qq.ucAll);
            }
            var fixed29 = c.MKT_YEAR + c.TEAM_YEAR + pr29.fix + (adv ? c.ADV_29 : 0.0) + recal;
            var profit29 = contrib29 - left29 * c.LEFT29 - fixed29;
            var t29 = dm29.rival + c.LOST_TO_RIVAL * (d29 - sold29);
            var share29 = sold29 / (sold29 + t29);
            var err1 = Math.abs(q1 - d1) / d1;
            var err29 = Math.abs(q29 - d29) / d29;
            return {
                a: a, study: st, design: d, price: price,
                fraw: fraw, q1: q1, d1: d1, sold1: sold1, left1: left1, lost1: lost1,
                p2: p2, d2: d2, f2est: f2est, fromStock: fromStock, writtenOff: writtenOff, reach2: reach2,
                share28: share28, reach29: reach29, profit28: profit28,
                d29: d29, f29est: f29est, calib: calib, q29: q29, sold29: sold29, left29: left29, units29: units29,
                prods29: pr29.list, profit29: profit29, share29: share29,
                profit: profit28 + profit29, share: share29, err1: err1, err29: err29, err: (err1 + err29) / 2.0,
                spend: st.cost + recal, units: sold1 + d2 + sold29, orders29: d29 * c.ORDERS, extrap29: sold1 / c.LAUNCH_MONTHS * 12.0
            };
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._run(this._flat(state, period), period);
            return { score: this._scoreOf(m), m: m };
        }

        _scoreOf(m) {
            var c = this.C;
            var p = this._clamp((m.profit - c.P_LO) / (c.P_HI - c.P_LO), 0, 1);
            var e = this._clamp((c.E_LO - m.err) / (c.E_LO - c.E_HI), 0, 1);
            var s = this._clamp((m.share - c.S_LO) / (c.S_HI - c.S_LO), 0, 1);
            var W = c.W_P + c.W_E + c.W_S;
            return this._jsround(this._clamp(100.0 * (c.W_P * p + c.W_E * e + c.W_S * s) / W, 0, 100));
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            var l = (sim && sim.language) ? sim.language : ((sim && sim.currentLanguage) ? sim.currentLanguage : '');
            if (!l && document.documentElement && document.documentElement.getAttribute) { l = document.documentElement.getAttribute('lang') || ''; }
            return (String(l || 'es').toLowerCase().indexOf('en') === 0) ? 'en' : 'es';
        }

        _fmtNum(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'es') ? '.' : ',';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (Math.round(n) < 0 ? '-' : '') + out;
        }

        _fmtEur(n) {
            var body = this._fmtNum(n);
            return (this._lang() === 'es') ? (body + ' €') : (body.charAt(0) === '-' ? '-€' + body.slice(1) : '€' + body);
        }

        _fmtMill(n) {
            var v = Math.round(n / 10000) / 100;
            var s = v.toFixed(2);
            if (this._lang() === 'es') { return s.replace('.', ',') + ' M€'; }
            return (v < 0 ? '-€' + s.slice(1) : '€' + s) + 'M';
        }

        _dec(n, d) {
            var s = (Math.round(n * Math.pow(10, d)) / Math.pow(10, d)).toFixed(d);
            if (this._lang() === 'es') { s = s.replace('.', ','); }
            return s;
        }

        _one(n) {
            return this._dec(n, 1);
        }

        _pct(n) {
            return (this._lang() === 'es') ? (this._one(n) + ' %') : (this._one(n) + '%');
        }

        _pct0(x) {
            var v = Math.round(x * 100);
            return (this._lang() === 'es') ? (v + ' %') : (v + '%');
        }

        _fill(key, map) {
            var s = this._t(key);
            var t;
            for (t in map) { if (Object.prototype.hasOwnProperty.call(map, t)) { s = s.split(t).join(map[t]); } }
            return s;
        }

        _esc(s) {
            return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _html(id, html) {
            var el = document.getElementById(id);
            if (el) { el.innerHTML = html; }
        }

        _show(id, on) {
            var el = document.getElementById(id);
            if (el) { el.style.display = on ? '' : 'none'; }
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _bindUI() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            var on = function(id, fn) {
                var el = document.getElementById(id);
                if (el && el.addEventListener) { el.addEventListener('change', fn); }
            };
            ['metodo1', 'atributos1', 'muestra1'].forEach(function(id) {
                on(id, function() { self._renderR1Live(); self._renderSampleCI(); });
            });
            var mirror = { autonomia2: 'simRange', motor2: 'simMotor', bateria2: 'simBattery' };
            ['autonomia2', 'motor2', 'bateria2', 'precio2', 'serie2'].forEach(function(id) {
                on(id, function() {
                    var st = window.mySimulation ? window.mySimulation.state : null;
                    if (mirror[id]) {
                        var src = document.getElementById(id);
                        var dst = document.getElementById(mirror[id]);
                        if (src && dst) { dst.value = src.value; }
                    }
                    if (id === 'precio2') {
                        var sp = document.getElementById('simPrice');
                        var pv = document.getElementById('precio2');
                        if (sp && pv) { sp.value = pv.value.slice(1); }
                    }
                    self._renderR2Live(st);
                    self._renderSim(st);
                });
            });
            ['simRange', 'simMotor', 'simBattery', 'simPrice', 'simResp', 'simExt', 'simUpdate', 'simReach', 'simAssume'].forEach(function(id) {
                on(id, function() { self._renderSim(window.mySimulation ? window.mySimulation.state : null); });
            });
            if (document.addEventListener) {
                document.addEventListener('express:langchanged', function() {
                    if (window.mySimulation) { self._updateBriefing(window.mySimulation.state); }
                });
            }
        }

        _ctx(state) {
            var ds = (state && state.domainState) || {};
            var done = !!ds.finished && this._completed(state) >= this.ROUNDS.length;
            var period = (state && state.currentPeriod) || 1;
            return { done: done, period: done ? 5 : period };
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var cx = this._ctx(state);
            var period = forcedPeriod || state.currentPeriod || 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = cx.done ? this._t('round_done') : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var pH = ds.profitHistory || [];
            var sH = ds.shareHistory || [];
            var eH = ds.errHistory || [];
            var spH = ds.spendHistory || [];
            var uH = ds.unitsHistory || [];
            var n = pH.length;
            this._set('profitDisplay', n ? (this._fmtMill(pH[n - 1]) + ' · ' + this._pct(sH[n - 1]) + ' ' + this._t('txt_share')) : '-');
            this._set('researchDisplay', n ? (this._pct(eH[n - 1]) + ' ' + this._t('txt_err') + ' · ' + this._fmtEur(spH[n - 1]) + ' ' + this._t('txt_spend')) : '-');
            this._set('unitsDisplay', n ? (this._fmtNum(uH[n - 1]) + ' ' + this._t('txt_units')) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                this._show(this.ROUNDS[i].panel, !cx.done && (i + 1) === period);
            }
            this._show('actionsRow', !cx.done);
            this._show('labPanel', cx.done || period >= 2);
            this._syncControlsFromDecisions(state);
            this._renderStatic();
            this._renderR1Live();
            this._renderSampleCI();
            if (cx.done || period >= 2) {
                this._renderR2Info(state);
                this._renderStudy(state);
            }
            if (!cx.done && period === 2) { this._renderR2Live(state); }
            if (!cx.done && period === 3) { this._renderReveal3(state); this._renderR3Info(state); }
            if (!cx.done && period === 4) { this._renderReveal4(state); this._renderR4Info(state); }
            this._prepareSim(state);
            this._renderSim(state);
        }

        _renderStatic() {
            var self = this;
            var es = (this._lang() === 'es');
            var comp = document.getElementById('ecCompBody');
            if (comp) {
                var kg = function(v) { return (v >= 0 ? '+' : '') + self._dec(v, 1) + ' kg'; };
                var rows = [
                    ['ec_base60', this._fmtEur(this.RANGE_UC[0]), this._dec(this.RANGE_KG[0], 1) + ' kg'],
                    ['ec_r90', '+' + this._fmtEur(this.RANGE_UC[1] - this.RANGE_UC[0]), kg(this.RANGE_KG[1] - this.RANGE_KG[0])],
                    ['ec_r120', '+' + this._fmtEur(this.RANGE_UC[2] - this.RANGE_UC[0]), kg(this.RANGE_KG[2] - this.RANGE_KG[0])],
                    ['ec_motor', '+' + this._fmtEur(this.MOTOR_UC), kg(this.MOTOR_KG)],
                    ['ec_rem', '+' + this._fmtEur(this.REM_UC), kg(this.REM_KG)]
                ];
                comp.innerHTML = rows.map(function(r) {
                    return '<tr><th scope="row">' + self._esc(self._t(r[0])) + '</th><td>' + r[1] + '</td><td>' + r[2] + '</td></tr>';
                }).join('');
            }
            var net = document.getElementById('ecNetBody');
            if (net) {
                net.innerHTML = this.PRICES.map(function(pk) {
                    var p = self.PRICE[pk];
                    return '<tr><th scope="row">' + self._fmtEur(p) + '</th><td>' + self._fmtEur(self._net(p)) + '</td></tr>';
                }).join('');
            }
            ['panel', 'pequena', 'clientes', 'redes'].forEach(function(s) {
                var cap = s.charAt(0).toUpperCase() + s.slice(1);
                self._set('n' + cap, self._fmtNum(self.SAMPLE_N[s]));
                self._set('mix' + cap, Math.round(self.SAMPLE_MIX[s] * 100) + ' / ' + Math.round((1 - self.SAMPLE_MIX[s]) * 100));
            });
            var sp = document.getElementById('simPrice');
            if (sp && sp.options) {
                var o;
                for (o = 0; o < sp.options.length; o++) {
                    var opt = sp.options[o];
                    opt.textContent = this._fmtEur(parseFloat(opt.value));
                    opt.text = opt.textContent;
                }
            }
            var sr = document.getElementById('simReach');
            if (sr && sr.options) {
                var q;
                for (q = 0; q < sr.options.length; q++) {
                    var op = sr.options[q];
                    if (op.value !== '100') { op.textContent = es ? (op.value + ' %') : (op.value + '%'); op.text = op.textContent; }
                }
            }
            var sa = document.getElementById('simAssume');
            if (sa && sa.options) {
                var z;
                for (z = 0; z < sa.options.length; z++) {
                    var oz = sa.options[z];
                    if (oz.value !== '0') { oz.textContent = this._fmtEur(parseFloat(oz.value)); oz.text = oz.textContent; }
                }
            }
        }

        _attrList(study, wantMeasured) {
            var self = this;
            var out = [];
            ['rng', 'mot', 'kg', 'rem', 'war', 'gps'].forEach(function(k) {
                var m = !!study.measured[k];
                if (m === wantMeasured) { out.push(self._t('an_' + k)); }
            });
            return out;
        }

        _currentR1() {
            return {
                e: this._str('metodo1', this.DEFAULTS.metodo1),
                at: this._str('atributos1', this.DEFAULTS.atributos1),
                s: this._str('muestra1', this.DEFAULTS.muestra1)
            };
        }

        _renderR1Live() {
            var c = this._currentR1();
            var st = this._study(c.e, c.at, c.s);
            var a = document.getElementById('atributos1');
            var m = document.getElementById('muestra1');
            if (a) { a.disabled = st.none; }
            if (m) { m.disabled = st.none; }
            if (st.none) { this._set('r1Live', this._t('r1_live_none')); return; }
            var list = this._attrList(st, true);
            list.push(this._t('an_price'));
            list.push(this._t('an_brand'));
            this._set('r1Live', this._fill('r1_live', { '%C%': this._fmtEur(st.cost), '%W%': String(st.weeks), '%A%': list.join(', ') }));
        }

        _wtpSe(par, se, du, sdu) {
            var b = -par.pr;
            if (b <= 0) { return { w: 0, ci: 0 }; }
            var w = 100.0 * du / b;
            var sw = 100.0 * Math.sqrt(Math.pow(sdu / b, 2) + Math.pow(du * (se.pr || 0) / (b * b), 2));
            return { w: w, ci: 1.96 * sw };
        }

        _renderSampleCI() {
            var c = this._currentR1();
            var self = this;
            var ids = { panel: 'ciPanel', pequena: 'ciPequena', clientes: 'ciClientes', redes: 'ciRedes' };
            Object.keys(ids).forEach(function(s) {
                var st = self._study(c.e, c.at, s);
                if (st.none) { self._set(ids[s], self._t('ci_none')); return; }
                var u = self._wtpSe(st.model.U, st.se.U, st.model.U.kg, st.se.U.kg);
                var parts = [self._fill('ci_kg', { '%V%': self._fmtEur(u.ci) })];
                if (st.measured.mot) {
                    var e = self._wtpSe(st.model.E, st.se.E, st.model.E.mot, st.se.E.mot);
                    parts.push(self._fill('ci_mot', { '%V%': self._fmtEur(e.ci) }));
                } else {
                    parts.push(self._t('ci_mot_no'));
                }
                self._set(ids[s], parts.join(' · '));
            });
        }

        _planStudy(state) {
            var d = this._flat(state, 1);
            var a = this._active(d, 1);
            return this._study(a.metodo1, a.atributos1, a.muestra1);
        }

        _renderR2Info(state) {
            var st = this._planStudy(state);
            if (st.none) {
                this._set('r2Measured', this._t('r2_measured_none'));
            } else {
                var ml = this._attrList(st, true);
                ml.push(this._t('an_price'));
                ml.push(this._t('an_brand'));
                this._set('r2Measured', this._fill('r2_measured', { '%A%': ml.join(', ') }));
            }
            var bias = this._t('r2_bias_' + st.method);
            if (!st.none && st.sample !== 'panel') { bias += ' ' + this._t('r2_bias_s_' + st.sample); }
            this._set('r2Bias', bias);
            var ul = this._attrList(st, false);
            this._set('r2Unmeasured', ul.length ? this._fill('r2_unmeasured', { '%A%': ul.join(', ') }) : this._t('unmeasured_empty'));
        }

        _renderR2Live(state) {
            var st = this._planStudy(state);
            var d = this._design(this._str('autonomia2', this.DEFAULTS.autonomia2), this._str('motor2', this.DEFAULTS.motor2), this._str('bateria2', this.DEFAULTS.bateria2));
            var p = this.PRICE[this._str('precio2', this.DEFAULTS.precio2)] || 2590.0;
            var f = this._launchForecast(st, d, p);
            var q = Math.min(this.C.CAP_RUN, (this.SERIE[this._str('serie2', this.DEFAULTS.serie2)] || 1.0) * f);
            this._set('r2Live', this._fill('r2_live', {
                '%KG%': this._dec(d.kg, 1), '%UC%': this._fmtEur(d.uc), '%NET%': this._fmtEur(this._net(p)),
                '%MG%': this._fmtEur(this._net(p) - d.uc), '%F%': this._fmtNum(f), '%Q%': this._fmtNum(q)
            }));
        }

        _renderReveal3(state) {
            var m = this._run(this._flat(state, 2), 2);
            var x;
            if (m.lost1 > m.d1 * 0.03) { x = this._fill('r3_short', { '%K%': this._fmtNum(m.lost1) }); }
            else if (m.left1 > m.d1 * 0.03) { x = this._fill('r3_left', { '%L%': this._fmtNum(m.left1) }); }
            else { x = this._t('r3_exact'); }
            this._set('r3Reveal', this._fill('r3_reveal', {
                '%F%': this._fmtNum(m.fraw), '%Q%': this._fmtNum(m.q1), '%D%': this._fmtNum(m.d1), '%S%': this._fmtNum(m.sold1),
                '%X%': x, '%R%': this._dec(m.sold1 / m.fraw, 2)
            }));
        }

        _renderR3Info(state) {
            var st = this._planStudy(state);
            var ml = this._attrList(st, true);
            this._set('r3Measured', st.none ? this._t('r2_measured_none') : this._fill('r3_measured', { '%A%': ml.concat([this._t('an_price'), this._t('an_brand')]).join(', ') }));
            var ul = this._attrList(st, false);
            this._set('r3Unmeasured', ul.length ? this._fill('r3_unmeasured', { '%A%': ul.join(', ') }) : this._t('unmeasured_empty'));
        }

        _renderReveal4(state) {
            var m = this._run(this._flat(state, 3), 3);
            this._set('r4Reveal', this._fill('r4_reveal', {
                '%F%': this._fmtNum(m.f2est), '%D%': this._fmtNum(m.d2), '%R%': this._dec(m.d2 / m.f2est, 2),
                '%S%': this._pct0(m.share28), '%A%': this._pct0(m.reach29)
            }));
        }

        _renderR4Info(state) {
            var dec = this._flat(state, 3);
            dec.mejora4 = 'igual';
            dec.prevision4 = 'calibrar';
            var m = this._run(dec, 4);
            this._set('r4Numbers', this._fill('r4_numbers', {
                '%E%': this._fmtNum(m.extrap29), '%P%': this._fmtNum(m.orders29), '%C%': this._fmtNum(m.calib)
            }));
            var st = m.study;
            var ul = this._attrList(st, false);
            if (!st.none && st.measured.rng) { ul.push(this._t('an_150')); }
            this._set('r4Unmeasured', ul.length ? this._fill('r4_unmeasured', { '%A%': ul.join(', ') }) : this._t('unmeasured_empty'));
        }

        _ciTxt(v, ci) {
            if (ci === null || ci === undefined) { return this._dec(v, 2); }
