                var dev = Math.abs(st.model.U.pr - T.U.pr) / (-T.U.pr);
                out.push(this._fill('fb_m_' + st.method, { '%P%': this._pct0(dev) }));
                if (st.attrs === 'ingenieria') { out.push(this._fill('fb_a_ingenieria', { '%W%': eur(this._trueWtp('U', T.U.rem)) })); }
                else if (st.attrs === 'voz') { out.push(this._fill('fb_a_voz', { '%W%': eur(this._trueWtp('E', T.E.mot)) })); }
                else { out.push(this._t('fb_a_todo')); }
                out.push(this._t('fb_s_' + st.sample));
            }
            var vname = this.RANGE_KM[m.design.r] + ' km · ' + this._t('vn_' + (m.design.m ? 'central' : 'buje')) + ' · ' + this._t('vn_' + (m.design.rem ? 'extraible' : 'integrada'));
            out.push(this._fill('fb_design', {
                '%V%': vname, '%P%': eur(m.price), '%K%': this._dec(m.design.kg, 1), '%MG%': eur(this._net(m.price) - m.design.uc), '%SH%': this._pct0(m.share28)
            }));
            var dev1 = (m.q1 - m.d1) / m.d1;
            if (dev1 > 0.10) { out.push(this._fill('fb_serie_over', { '%P%': this._pct0(dev1), '%L%': this._fmtNum(m.left1) })); }
            else if (dev1 < -0.10) { out.push(this._fill('fb_serie_under', { '%P%': this._pct0(-dev1), '%K%': this._fmtNum(m.lost1) })); }
            else { out.push(this._t('fb_serie_ok')); }
            var r = a.respuesta3;
            out.push(this._fill('fb_r_' + r, {
                '%S%': this._pct0(m.share28), '%A%': this._pct0(m.reach29),
                '%W%': eur(this._trueWtp('U', T.U.war)), '%W2%': eur(this._trueWtp('E', T.E.war))
            }));
            if (a.gama3 === 'ninguna') {
                out.push(this._t('fb_g_ninguna'));
            } else {
                var est = this._demand(st.model, m.prods29, this.RIVAL29, this.C.W_YEAR, 1.0).units[1] * (m.reach29);
                var act = m.units29[1] || 0;
                var xq = m.prods29[1];
                var low = [];
                if (xq.m && (st.none || !st.measured.mot || st.model.E.mot < T.E.mot * 0.85)) { low.push(this._t('an_mot')); }
                if (xq.rem && (st.none || !st.measured.rem || st.model.U.rem < T.U.rem * 0.85)) { low.push(this._t('an_rem')); }
                if (xq.r >= 2 && (st.none ? false : (st.model.E.rng[2] < T.E.rng[2] * 0.85))) { low.push(this._t('an_rng')); }
                if (!low.length) { low.push(this._t('txt_estimated_low')); }
                var gk = (est > act * 1.15) ? 'fb_g_over' : ((est < act * 0.85) ? 'fb_g_under' : 'fb_g_ok');
                out.push(this._fill(gk, { '%N%': this._t('pn_' + a.gama3), '%U%': this._fmtNum(act), '%E%': this._fmtNum(est), '%A%': low.join(', ') }));
            }
            var u = a.mejora4;
            var r0 = Math.min(3, m.design.r + 1);
            var wU, wE;
            if (u === 'autonomia') {
                wU = this._trueWtp('U', T.U.rng[r0] - T.U.rng[m.design.r] - T.U.kg * this.C.UPG_RANGE_KG);
                wE = this._trueWtp('E', T.E.rng[r0] - T.E.rng[m.design.r] - T.E.kg * this.C.UPG_RANGE_KG);
            } else if (u === 'peso') {
                wU = this._trueWtp('U', T.U.kg * this.C.UPG_KG); wE = this._trueWtp('E', T.E.kg * this.C.UPG_KG);
            } else {
                wU = this._trueWtp('U', T.U.gps); wE = this._trueWtp('E', T.E.gps);
            }
            out.push(this._fill('fb_u_' + u, { '%W%': eur(wU), '%W2%': eur(wE), '%S%': this._pct0(m.share29) }));
            out.push(this._fill('fb_p_' + a.prevision4, { '%E%': this._pct0(m.err29) }));
            out.push(this._t('fb_next'));
            return out;
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var m = this._run(this._flat(state, mm), mm);
            var bot = this._botRun();
            var composite = this._composite(state);
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceKey: vk,
                performanceLabel: this._t(vk),
                profit: Math.round(m.profit),
                share: Math.round(m.share * 1000) / 10,
                err: Math.round(m.err * 1000) / 10,
                spend: Math.round(m.spend),
                units: Math.round(m.units),
                botProfit: Math.round(bot.profit),
                botShare: Math.round(bot.share * 1000) / 10,
                botErr: Math.round(bot.err * 1000) / 10,
                botUnits: Math.round(bot.units),
                periods: (history || []).length,
                insights: this._insights(m)
            };
        }

        _truthTable(m) {
            var st = m.study;
            var self = this;
            var T = this.TRUTH;
            var t = function(k) { return self._esc(self._t(k)); };
            var na = '<span class="ej2474-na">' + t('txt_notmeasured') + '</span>';
            var rows = [
                ['wtp_rng1', function(p) { return p.rng[1]; }, 'rng1', 'rng'],
                ['wtp_rng2', function(p) { return p.rng[2] - p.rng[1]; }, 'rng', 'rng'],
                ['row_mot', function(p) { return p.mot; }, 'mot', 'mot'],
                ['row_kg', function(p) { return p.kg; }, 'kg', 'kg'],
                ['row_rem', function(p) { return p.rem; }, 'rem', 'rem'],
                ['row_war', function(p) { return p.war; }, 'war', 'war'],
                ['row_gps', function(p) { return p.gps; }, 'gps', 'gps'],
                ['row_brand', function(p) { return p.brand; }, 'brand', null]
            ];
            var h = '<table class="ej2474-data"><caption>' + t('cm_truth_title') + '</caption><thead><tr><th scope="col">' + t('th_attr') + '</th><th scope="col">' + t('cm_th_ue') + '</th><th scope="col">' + t('cm_th_ut') + '</th><th scope="col">' + t('cm_th_ee') + '</th><th scope="col">' + t('cm_th_et') + '</th></tr></thead><tbody>';
            rows.forEach(function(r) {
                var meas = (r[3] === null) || (st.none ? (['rng', 'mot', 'kg'].indexOf(r[3]) >= 0) : !!st.measured[r[3]]);
                var cells = ['U', 'E'].map(function(g) {
                    var est = meas ? self._fmtEur(100.0 * r[1](st.model[g]) / (-st.model[g].pr)) : na;
                    var tru = self._fmtEur(100.0 * r[1](T[g]) / (-T[g].pr));
                    return '<td>' + est + '</td><td><strong>' + tru + '</strong></td>';
                }).join('');
                h += '<tr><th scope="row">' + t(r[0]) + '</th>' + cells + '</tr>';
            });
            h += '<tr><th scope="row">' + t('row_price') + '</th>' + ['U', 'E'].map(function(g) {
                return '<td>' + self._dec(st.model[g].pr, 2) + '</td><td><strong>' + self._dec(T[g].pr, 2) + '</strong></td>';
            }).join('') + '</tr>';
            h += '</tbody></table>';
            return h;
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var state = window.mySimulation ? window.mySimulation.state : null;
            var n = state ? Math.max(1, this._completed(state)) : 4;
            var m = state ? this._run(this._flat(state, n), n) : this._run({}, 4);
            var self = this;
            var items = (s.insights || []).map(function(x) { return '<li>' + self._esc(x) + '</li>'; }).join('');
            var dfull = m.d1 / this.C.REACH28;
            var b;
            if (m.study.none) { b = this._t('cm_fc_none'); }
            else {
                var gap = m.fraw / dfull - 1.0;
                if (gap > 0.05) { b = this._fill('cm_fc_over', { '%P%': this._pct0(gap) }); }
                else if (gap < -0.05) { b = this._fill('cm_fc_under', { '%P%': this._pct0(-gap) }); }
                else { b = this._t('cm_fc_ok'); }
            }
            var fc = '<p>' + this._esc(this._fill('cm_fc_launch', { '%F%': this._fmtNum(m.fraw), '%Q%': this._fmtNum(m.q1), '%D%': this._fmtNum(m.d1), '%DF%': this._fmtNum(dfull), '%B%': b })) + '</p>'
                + '<p>' + this._esc(this._fill('cm_fc_2029', { '%Q%': this._fmtNum(m.q29), '%D%': this._fmtNum(m.d29), '%E%': this._pct0(m.err29) })) + '</p>';
            var qs = ['cm_q1', 'cm_q2', 'cm_q3', 'cm_q4'].map(function(k) { return '<li>' + self._esc(self._t(k)) + '</li>'; }).join('');
            return '<div class="ej2474-cm">'
                + '<div class="ej2474-cm-score">' + score + '<span class="ej2474-cm-max">/100</span></div>'
                + '<div class="ej2474-cm-verdict">' + this._esc(s.performanceLabel || '') + '</div>'
                + '<div class="ej2474-cm-kpis">'
                + '<div class="ej2474-cm-kpi">' + this._esc(this._t('cm_kpi_profit')) + ' <strong>' + this._fmtEur(s.profit || 0) + '</strong></div>'
                + '<div class="ej2474-cm-kpi">' + this._esc(this._t('cm_kpi_share')) + ' <strong>' + this._pct(s.share || 0) + '</strong></div>'
                + '<div class="ej2474-cm-kpi">' + this._esc(this._t('cm_kpi_err')) + ' <strong>' + this._pct(s.err || 0) + '</strong></div>'
                + '<div class="ej2474-cm-kpi">' + this._esc(this._t('cm_kpi_spend')) + ' <strong>' + this._fmtEur(s.spend || 0) + '</strong></div>'
                + '<div class="ej2474-cm-kpi">' + this._esc(this._t('cm_kpi_units')) + ' <strong>' + this._fmtNum(s.units || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2474-cm-bot">' + this._esc(this._t('cm_bot')) + ' '
                + this._esc(this._t('cm_kpi_profit')) + ' <strong>' + this._fmtEur(s.botProfit || 0) + '</strong> · '
                + this._esc(this._t('cm_kpi_share')) + ' <strong>' + this._pct(s.botShare || 0) + '</strong> · '
                + this._esc(this._t('cm_kpi_err')) + ' <strong>' + this._pct(s.botErr || 0) + '</strong></div>'
                + '<p class="ej2474-cm-equiv">' + this._esc(this._t('cm_equiv')) + '</p>'
                + '<div class="ej2474-tablewrap">' + this._truthTable(m) + '</div>'
                + '<h4 class="ej2474-cm-h">' + this._esc(this._t('cm_fc_title')) + '</h4>' + fc
                + '<h4 class="ej2474-cm-h">' + this._esc(this._t('cm_debrief')) + '</h4>'
                + '<ul class="ej2474-cm-insights">' + items + '</ul>'
                + '<h4 class="ej2474-cm-h">' + this._esc(this._t('cm_debate_title')) + '</h4>'
                + '<ol class="ej2474-cm-questions">' + qs + '</ol>'
                + '</div>';
        }

